  'scoring.intro':
    'In ranked matches your rating updates with the standard Elo formula. How much you win or lose depends on your opponent’s rating: beating a stronger player earns more, losing to a weaker one costs more.',
  'scoring.formula.text': 'New Rating = Current Rating + 32 × (Result − Expected)',
  'scoring.formula.expl':
    'Result is 1 for a win and 0 for a loss. Expected is your win probability and drops as the opponent gets stronger: Expected = 1 / (1 + 10^((Opponent − You) / 400)). The K factor is 32.',
