    'Dice come from a secret seed fixed at the start of the match. Its hash (commitment) is shown up front; the seed is revealed when the match ends. So you can verify yourself that the dice were not altered afterwards.',
  'fair.commitment': 'Commitment (SHA-256 hash)',
  'fair.clientSeed': 'Client seed',
  'fair.serverSeed': 'Server seed',
  'fair.hidden': 'Revealed when the match ends',
  'fair.rolls': 'Rolls this match: {n}',
  'fair.verifyTitle': 'Verify',
  'fair.verifyBtn': 'Compute Roll',
  'fair.dice': 'Dice',
  'fair.hashOk': 'Hash matches — seed is consistent with the commitment.',
  'fair.hashBad': 'Hash does not match.',
  'fair.howTitle': 'How Does Fair Dice Work?',
  'fair.howSub': 'The dice are secured before the match starts. After it ends, you can check the outcome yourself.',
  'fair.s1.title': 'The Dice Are Locked',
  'fair.s1.desc': 'Before the match starts, the secret information that generates the dice is prepared.',
  'fair.s1.sub': 'No one can change the outcome yet.',
  'fair.s2.title': 'You Get a Proof',
  'fair.s2.desc': 'Before the match starts, the system shows you a unique digital fingerprint.',
  'fair.s2.sub': 'Think of it like the label on a sealed box.',
  'fair.s3.title': 'The Dice Are Rolled',
  'fair.s3.desc': 'Throughout the match, the dice are computed using this locked information.',
  'fair.s4.title': 'Check It Yourself',
  'fair.s4.desc': 'When the match ends the secret is revealed. You can check it matches the proof given at the start.',
  'fair.s4.badge': 'Matches',
  'fair.s4.sub': 'The dice were not changed.',
  'fair.box.title': 'Think of a Sealed Box',
  'fair.box.1': 'The site locks a box.',
  'fair.box.2': 'It gives you the box’s label.',
  'fair.box.3': 'When the match ends it opens the box.',
  'fair.box.result': 'If the label matches, no one touched the box.',
  'fair.callout.title': 'The dice cannot be changed afterwards.',
  'fair.callout.sub': 'At the end of the match you can verify the outcome yourself using all the information.',
  'fair.techToggle': 'Show technical details',
  'fair.techToggleHide': 'Hide technical details',
  'fair.copied': 'Copied to clipboard',
