  'fair.verify.okDesc': 'This roll matches exactly the information used during the match.',
  'fair.verify.badTitle': 'No Match',
  'fair.verify.badDesc': 'The information entered does not match this match’s records.',
  // ---- Info › Fair Dice page (redesign) ----
  'fairp.hero.title': '100% Fair & Secure Dice',
  'fairp.hero.intro1':
    'In backgammon you sometimes get great rolls and sometimes terrible ones. That is a natural part of the game.',
  'fairp.hero.intro2':
    'No player is ever given special dice. The system does not take into account who is winning, who is losing, or who is playing.',
  'fairp.hero.quote': 'The dice don’t know you. They don’t know your opponent. Every roll is random.',
  'fairp.s1.title': 'How Are the Dice Rolled?',
  'fairp.s1.p1': 'On every roll the computer generates a random number between 1 and 6.',
  'fairp.s1.p2': 'It uses a strong random number system built for security (a CSPRNG) to do this.',
  'fairp.s1.p3': 'So the dice are not prepared and lined up in advance. Each roll is created right at that moment.',
  'fairp.s2.title': 'Is It Possible to Know the Next Roll?',
  'fairp.s2.no': 'No.',
  'fairp.s2.p1': 'For example, getting three 6s in a row tells you nothing about what the next roll will be.',
  'fairp.s2.p2': 'Players, bots, and even the people who build the system cannot know the next roll in advance.',
  'fairp.s3.title': 'Can the System Favor a Player?',
  'fairp.s3.no': 'No.',
  'fairp.s3.lead': 'The dice system does not look at the player’s:',
  'fairp.s3.i1': 'Identity',
  'fairp.s3.i2': 'Rating',
  'fairp.s3.i3': 'Win/loss record',
  'fairp.s3.i4': 'Premium status',
  'fairp.s3.i5': 'Coin balance',
  'fairp.s3.i6': 'Opponent',
  'fairp.s3.i7': 'Bot-or-human status',
  'fairp.s3.foot': 'The same dice system runs for everyone.',
  'fairp.s4.title': 'You Can Check It Yourself',
  'fairp.s4.p1': 'We don’t just say “trust us.”',
  'fairp.s4.p2':
    'The dice system we use is open source. Anyone who understands code can inspect it and check how the dice are generated.',
  'fairp.s4.cta': 'View the Code on GitHub',
  'fairp.tech.toggle': 'Show Technical Details',
  'fairp.tech.toggleHide': 'Hide Technical Details',
  'fairp.tech.body':
    'The dice are generated with a cryptographically secure random number generator (CSPRNG). Each byte is reduced to the range 0–251 (rejection sampling), so faces 1–6 come up with exactly equal probability — there is no “modulo bias.” The test below uses the very same roll function used in real games.',
  'fairp.test.title': 'Test the Dice Yourself',
  'fairp.test.sub': 'Try the system yourself. Roll thousands of dice and see how the results are distributed.',
  'fairp.test.countLabel': 'How many dice?',
  'fairp.test.custom': 'Custom',
  'fairp.test.start': 'Start Test',
  'fairp.test.again': 'Test Again',
  'fairp.test.running': 'Rolling…',
  'fairp.test.times': 'times',
  'fairp.test.expectedLine': 'Expected · 16.67%',
  'fairp.test.summary': 'With fair dice, each number is expected to come up roughly 16.67% of the time over the long run.',
  'fairp.test.note':
    'Over 100 or 1,000 rolls the ratios don’t have to be exactly 16.67%. As the number of rolls grows, the results get closer to 16.67%.',
  'fairp.test.stat.total': 'Total rolls',
  'fairp.test.stat.most': 'Most frequent',
  'fairp.test.stat.least': 'Least frequent',
  'fairp.test.stat.avg': 'Average',
  'fairp.test.stat.expected': 'Expected rate',
  'fairp.test.dist.ok': 'Within the normal distribution range',
  'fairp.test.dist.anomaly': 'This sample shows a distribution different from expected',
  'fairp.test.dist.okDesc': 'No unusual deviation was seen in this sample.',
  'fairp.test.dist.caveat':
    'This result alone does not prove the whole system; larger samples are more meaningful for examining the distribution.',
  'fairp.test.dist.note':
    'This test checks whether the rolls deviate unusually from the expected distribution across faces 1–6.',
  'fairp.test.dist.detail': 'Distribution Test — details',
  'fairp.test.dist.chi': 'Chi-square value',
  'fairp.test.dist.p': 'p-value',
  'fairp.test.infobox':
    'This test lets you see how the dice are distributed. Short-term differences are normal in random systems. What matters is that, over many rolls, the results approach a balanced distribution.',
  'fairp.verify.title': 'Verify a Roll With the Seeds',
  'fairp.verify.sub':
    'Below are seeds generated for an example match. Press “Verify”: see that the commitment (fingerprint) matches the seed and that the roll was computed from it. Change any value and the match breaks.',
  'fairp.verify.commitment': 'Commitment (SHA-256 fingerprint)',
  'fairp.verify.serverLabel': 'Server Seed',
  'fairp.verify.clientLabel': 'Client Seed',
  'fairp.verify.nonceLabel': 'Roll Number',
  'fairp.verify.cta': 'Verify',
  'fairp.verify.regen': 'Generate new example',
  'fairp.verify.okTitle': 'Verified',
  'fairp.verify.okDesc': 'The seed matches the original commitment exactly, and the roll was computed from that seed.',
  'fairp.verify.badTitle': 'No Match',
  'fairp.verify.badDesc':
    'The values were changed, so they no longer match the original commitment. In a real match this would mean the dice were tampered with.',
  'fairp.verify.note':
    'These seeds are an example generated in your browser. In real matches, when the match ends you can see your own seeds and verify them the same way.',
