  'scoring.intro':
    'Στους κατατασσόμενους αγώνες η βαθμολογία σου ενημερώνεται με τον στάνταρ τύπο Elo. Το πόσο κερδίζεις ή χάνεις εξαρτάται από τη βαθμολογία του αντιπάλου σου: το να νικήσεις έναν ισχυρότερο παίκτη αποφέρει περισσότερα, το να χάσεις από έναν ασθενέστερο κοστίζει περισσότερα.',
  'scoring.formula.text': 'Νέα Βαθμολογία = Τρέχουσα Βαθμολογία + 32 × (Αποτέλεσμα − Αναμενόμενο)',
  'scoring.formula.expl':
    'Το Αποτέλεσμα είναι 1 για νίκη και 0 για ήττα. Το Αναμενόμενο είναι η πιθανότητα νίκης σου και μειώνεται καθώς ο αντίπαλος γίνεται ισχυρότερος: Αναμενόμενο = 1 / (1 + 10^((Αντίπαλος − Εσύ) / 400)). Ο συντελεστής K είναι 32.',
