  'scoring.intro':
    'В рейтинговых матчах ваш рейтинг обновляется по стандартной формуле Elo. Сколько вы выигрываете или теряете, зависит от рейтинга соперника: победа над более сильным игроком приносит больше, поражение от более слабого стоит больше.',
  'scoring.formula.text': 'Новый рейтинг = Текущий рейтинг + 32 × (Результат − Ожидаемое)',
  'scoring.formula.expl':
    'Результат равен 1 при победе и 0 при поражении. Ожидаемое — это ваша вероятность победы, которая падает по мере усиления соперника: Ожидаемое = 1 / (1 + 10^((Соперник − Вы) / 400)). Коэффициент K равен 32.',
  'scoring.yourRating': 'Ваш рейтинг: {n}',
  'scoring.tableHint': 'Что вы получаете или теряете в матче в зависимости от рейтинга соперника:',
